From 66ff4d86e16efb04d14895082631b65ef7d55af9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:07:35 +0100
Subject: [PATCH] kcms/workspace: add a setting to switch the workspace type

Switching between Plasma Desktop and another shell such as Bigscreen
meant logging out and picking a different session. Plasma can now change
shells live, so offer the installed ones here and switch when applied.

BUG: 470519
---
 kcms/workspaceoptions/CMakeLists.txt          |  7 ++--
 kcms/workspaceoptions/ui/main.qml             | 26 ++++++++++++++
 kcms/workspaceoptions/workspaceoptions.cpp    | 35 +++++++++++++++++++
 kcms/workspaceoptions/workspaceoptions.h      |  6 ++++
 .../workspaceoptions_shellsettings.kcfg       | 13 +++++++
 .../workspaceoptions_shellsettings.kcfgc      |  7 ++++
 6 files changed, 92 insertions(+), 2 deletions(-)
 create mode 100644 kcms/workspaceoptions/workspaceoptions_shellsettings.kcfg
 create mode 100644 kcms/workspaceoptions/workspaceoptions_shellsettings.kcfgc

diff --git a/kcms/workspaceoptions/CMakeLists.txt b/kcms/workspaceoptions/CMakeLists.txt
index 0d314288db..454322dc82 100644
--- a/kcms/workspaceoptions/CMakeLists.txt
+++ b/kcms/workspaceoptions/CMakeLists.txt
@@ -6,18 +6,20 @@ kcmutils_add_qml_kcm(kcm_workspace SOURCES workspaceoptions.cpp workspaceoptions
 kcmutils_generate_module_data(kcm_workspace
     MODULE_DATA_HEADER workspaceoptionsdata.h
     MODULE_DATA_CLASS_NAME WorkspaceOptionsData
-    SETTINGS_HEADERS workspaceoptions_plasmasettings.h workspaceoptions_kdeglobalssettings.h workspaceoptions_kwinsettings.h
-    SETTINGS_CLASSES WorkspaceOptionsPlasmaSettings WorkspaceOptionsGlobalsSettings WorkspaceOptionsKwinSettings
+    SETTINGS_HEADERS workspaceoptions_plasmasettings.h workspaceoptions_kdeglobalssettings.h workspaceoptions_kwinsettings.h workspaceoptions_shellsettings.h
+    SETTINGS_CLASSES WorkspaceOptionsPlasmaSettings WorkspaceOptionsGlobalsSettings WorkspaceOptionsKwinSettings WorkspaceOptionsShellSettings
 )

 kconfig_add_kcfg_files(kcm_workspace workspaceoptions_kdeglobalssettings.kcfgc GENERATE_MOC)
 kconfig_add_kcfg_files(kcm_workspace workspaceoptions_plasmasettings.kcfgc GENERATE_MOC)
 kconfig_add_kcfg_files(kcm_workspace workspaceoptions_kwinsettings.kcfgc GENERATE_MOC)
+kconfig_add_kcfg_files(kcm_workspace workspaceoptions_shellsettings.kcfgc GENERATE_MOC)

 target_link_libraries(kcm_workspace PRIVATE
     KF6::KCMUtilsQuick
     KF6::I18n
     KF6::ConfigGui
+    KF6::Package
     Qt::DBus
     Qt::Qml
 )
@@ -26,4 +28,5 @@ target_link_libraries(kcm_workspace PRIVATE
 install(FILES workspaceoptions_kdeglobalssettings.kcfg DESTINATION ${KDE_INSTALL_KCFGDIR})
 install(FILES workspaceoptions_plasmasettings.kcfg DESTINATION ${KDE_INSTALL_KCFGDIR})
 install(FILES workspaceoptions_kwinsettings.kcfg DESTINATION ${KDE_INSTALL_KCFGDIR})
+install(FILES workspaceoptions_shellsettings.kcfg DESTINATION ${KDE_INSTALL_KCFGDIR})

diff --git a/kcms/workspaceoptions/ui/main.qml b/kcms/workspaceoptions/ui/main.qml
index 13c6b17741..e719485646 100644
--- a/kcms/workspaceoptions/ui/main.qml
+++ b/kcms/workspaceoptions/ui/main.qml
@@ -44,6 +44,32 @@ KCM.SimpleKCM {
         Layout.fillWidth: true
         Kirigami.FormGroup {
             title: i18nc("@title:group", "Plasma")
+
+            Kirigami.FormEntry {
+                title: i18nc("@label:listbox", "Workspace type:")
+                visible: kcm.shells.length > 1
+                contentItem: QQC2.ComboBox {
+                    model: kcm.shells
+                    textRole: "name"
+                    valueRole: "id"
+                    currentIndex: kcm.shells.findIndex(shell => shell.id === kcm.shellSettings.shellPackage)
+                    onActivated: kcm.shellSettings.shellPackage = currentValue
+
+                    KCM.SettingStateBinding {
+                        configObject: kcm.shellSettings
+                        settingName: "shellPackage"
+                    }
+                }
+                trailingItems: Kirigami.ContextualHelpButton {
+                    Layout.alignment: Qt.AlignRight
+                    toolTipText: i18nc("@info:whatsthis contextualhelpbutton tooltip", "Switches the whole workspace to a different interface, for example one made for TVs or phones, without logging out. Each workspace type keeps its own panels and widgets.")
+                }
+            }
+
+            Kirigami.FormSeparator {
+                visible: kcm.shells.length > 1
+            }
+
             // Visual behavior settings
             Kirigami.FormEntry {
                 title: i18nc("Part of the sentence 'Allow Plasma to show panel and widget tooltips'", "Allow Plasma to show:")
diff --git a/kcms/workspaceoptions/workspaceoptions.cpp b/kcms/workspaceoptions/workspaceoptions.cpp
index 86dea5accd..639448532f 100644
--- a/kcms/workspaceoptions/workspaceoptions.cpp
+++ b/kcms/workspaceoptions/workspaceoptions.cpp
@@ -10,6 +10,7 @@
 #include <qqml.h>

 #include <KLocalizedString>
+#include <KPackage/PackageLoader>
 #include <KPluginFactory>

 #include <QDBusConnection>
@@ -20,6 +21,7 @@
 #include "workspaceoptions_kdeglobalssettings.h"
 #include "workspaceoptions_kwinsettings.h"
 #include "workspaceoptions_plasmasettings.h"
+#include "workspaceoptions_shellsettings.h"
 #include "workspaceoptionsdata.h"

 K_PLUGIN_FACTORY_WITH_JSON(KCMWorkspaceOptionsFactory, "kcm_workspace.json", registerPlugin<KCMWorkspaceOptions>(); registerPlugin<WorkspaceOptionsData>();)
@@ -30,6 +32,7 @@ KCMWorkspaceOptions::KCMWorkspaceOptions(QObject *parent, const KPluginMetaData
 {
     qmlRegisterAnonymousType<WorkspaceOptionsPlasmaSettings>("org.kde.plasma.workspaceoptions.kcm", 1);
     qmlRegisterAnonymousType<WorkspaceOptionsKwinSettings>("org.kde.plasma.workspaceoptions.kcm", 1);
+    qmlRegisterAnonymousType<WorkspaceOptionsShellSettings>("org.kde.plasma.workspaceoptions.kcm", 1);

     qmlRegisterUncreatableType<WorkspaceOptionsGlobalsSettings>("org.kde.plasma.workspaceoptions.kcm",
                                                                 1,
@@ -38,6 +41,18 @@ KCMWorkspaceOptions::KCMWorkspaceOptions(QObject *parent, const KPluginMetaData
                                                                 QStringLiteral("Registered for enum access only"));

     setButtons(Apply | Default | Help);
+
+    // Only offer real workspace shells, not fallback or developer packages such as Plasma Nano or the plasmoidviewer shell
+    const QList<KPluginMetaData> shellPackages = KPackage::PackageLoader::self()->listPackages(QStringLiteral("Plasma/Shell"));
+    for (const KPluginMetaData &shell : shellPackages) {
+        if (shell.value(QStringLiteral("X-Plasma-APIVersion")).isEmpty()) {
+            continue;
+        }
+        m_shells.append(QVariantMap{{QStringLiteral("id"), shell.pluginId()}, {QStringLiteral("name"), shell.name()}});
+    }
+    std::ranges::sort(m_shells, [](const QVariant &a, const QVariant &b) {
+        return a.toMap().value(QStringLiteral("name")).toString().localeAwareCompare(b.toMap().value(QStringLiteral("name")).toString()) < 0;
+    });
 }

 WorkspaceOptionsGlobalsSettings *KCMWorkspaceOptions::globalsSettings() const
@@ -55,10 +70,21 @@ WorkspaceOptionsKwinSettings *KCMWorkspaceOptions::kwinSettings() const
     return m_data->workspaceOptionsKwinSettings();
 }

+WorkspaceOptionsShellSettings *KCMWorkspaceOptions::shellSettings() const
+{
+    return m_data->workspaceOptionsShellSettings();
+}
+
+QVariantList KCMWorkspaceOptions::shells() const
+{
+    return m_shells;
+}
+
 void KCMWorkspaceOptions::save()
 {
     const bool primarySelectionSaved = m_data->workspaceOptionsKwinSettings()->findItem(QStringLiteral("primarySelection"))->isSaveNeeded();
     const bool smoothScrollSaved = m_data->workspaceOptionsGlobalsSettings()->findItem(QStringLiteral("smoothScroll"))->isSaveNeeded();
+    const bool shellSaved = m_data->workspaceOptionsShellSettings()->findItem(QStringLiteral("shellPackage"))->isSaveNeeded();

     KQuickManagedConfigModule::save();

@@ -91,6 +117,15 @@ void KCMWorkspaceOptions::save()
         message.setArguments({QVariant(enabled)});
         QDBusConnection::sessionBus().send(message);
     }
+
+    if (shellSaved) {
+        QDBusMessage message = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                              QStringLiteral("/PlasmaShell"),
+                                                              QStringLiteral("org.kde.PlasmaShell"),
+                                                              QStringLiteral("changeShell"));
+        message.setArguments({m_data->workspaceOptionsShellSettings()->shellPackage()});
+        QDBusConnection::sessionBus().asyncCall(message);
+    }
 }

 void KCMWorkspaceOptions::requestReboot()
diff --git a/kcms/workspaceoptions/workspaceoptions.h b/kcms/workspaceoptions/workspaceoptions.h
index e459411f1b..b79bbad1ba 100644
--- a/kcms/workspaceoptions/workspaceoptions.h
+++ b/kcms/workspaceoptions/workspaceoptions.h
@@ -13,6 +13,7 @@ class WorkspaceOptionsData;
 class WorkspaceOptionsGlobalsSettings;
 class WorkspaceOptionsPlasmaSettings;
 class WorkspaceOptionsKwinSettings;
+class WorkspaceOptionsShellSettings;

 class KCMWorkspaceOptions : public KQuickManagedConfigModule
 {
@@ -20,6 +21,8 @@ class KCMWorkspaceOptions : public KQuickManagedConfigModule
     Q_PROPERTY(WorkspaceOptionsGlobalsSettings *globalsSettings READ globalsSettings CONSTANT)
     Q_PROPERTY(WorkspaceOptionsPlasmaSettings *plasmaSettings READ plasmaSettings CONSTANT)
     Q_PROPERTY(WorkspaceOptionsKwinSettings *kwinSettings READ kwinSettings CONSTANT)
+    Q_PROPERTY(WorkspaceOptionsShellSettings *shellSettings READ shellSettings CONSTANT)
+    Q_PROPERTY(QVariantList shells READ shells CONSTANT)

 public:
     KCMWorkspaceOptions(QObject *parent, const KPluginMetaData &metaData);
@@ -30,6 +33,8 @@ public:
     WorkspaceOptionsGlobalsSettings *globalsSettings() const;
     WorkspaceOptionsPlasmaSettings *plasmaSettings() const;
     WorkspaceOptionsKwinSettings *kwinSettings() const;
+    WorkspaceOptionsShellSettings *shellSettings() const;
+    QVariantList shells() const;

 public Q_SLOTS:
     void save() override;
@@ -40,4 +45,5 @@ Q_SIGNALS:

 private:
     WorkspaceOptionsData *m_data;
+    QVariantList m_shells;
 };
diff --git a/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfg b/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfg
new file mode 100644
index 0000000000..503fdca335
--- /dev/null
+++ b/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfg
@@ -0,0 +1,13 @@
+<?xml version="1.0" encoding="UTF-8"?>
+<kcfg xmlns="http://www.kde.org/standards/kcfg/1.0"
+      xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
+      xsi:schemaLocation="http://www.kde.org/standards/kcfg/1.0
+      http://www.kde.org/standards/kcfg/1.0/kcfg.xsd" >
+  <kcfgfile name="plasmashellrc" />
+  <group name="Shell">
+    <entry name="shellPackage" key="ShellPackage" type="String">
+      <label>Plasma shell used for the workspace</label>
+      <default code="true">qEnvironmentVariable("PLASMA_DEFAULT_SHELL", QStringLiteral("org.kde.plasma.desktop"))</default>
+    </entry>
+  </group>
+</kcfg>
diff --git a/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfgc b/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfgc
new file mode 100644
index 0000000000..3eca072b3c
--- /dev/null
+++ b/kcms/workspaceoptions/workspaceoptions_shellsettings.kcfgc
@@ -0,0 +1,7 @@
+File=workspaceoptions_shellsettings.kcfg
+ClassName=WorkspaceOptionsShellSettings
+Mutators=true
+DefaultValueGetters=true
+GenerateProperties=true
+ParentInConstructor=true
+Notifiers=true
-- 
